        public void Dispose()
        {
            if (_isDisposed)
                return;

            _isDisposed = true;

            // 取消订阅聚合器事件
            _eventAggregator.LogsAggregated -= OnLogsAggregated;

            // 清空聚合器
            _eventAggregator.Clear();

            // 取消订阅集合变更事件
            _logEntries.CollectionChanged -= OnLogEntriesCollectionChanged;

            // 清空日志
